package com.optarena.app

import java.io.ByteArrayInputStream
import javax.xml.parsers.DocumentBuilderFactory

object XmlConfigParser {
    // Return the text content of the root element of an XML config string.
    // BUG: the default DocumentBuilderFactory resolves external entities, so
    // a DOCTYPE with a SYSTEM entity (XXE) can read local files / SSRF.
    fun rootText(xml: String): String {
        val factory = DocumentBuilderFactory.newInstance()
        val builder = factory.newDocumentBuilder()
        val doc = builder.parse(ByteArrayInputStream(xml.toByteArray(Charsets.UTF_8)))
        return doc.documentElement.textContent
    }
}

