package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Test
import java.io.File

class XmlConfigParserTest {

    @Test
    fun parsesPlainXml() {
        assertEquals("hello", XmlConfigParser.rootText("<value>hello</value>"))
    }

    @Test
    fun doesNotResolveExternalEntities() {
        File("secret.txt").writeText("TOPSECRET-XYZ")
        val payload =
            "<?xml version=\"1.0\"?><!DOCTYPE v [<!ENTITY x SYSTEM \"file:secret.txt\">]><value>&x;</value>"
        val leaked = try {
            XmlConfigParser.rootText(payload)
        } catch (e: Exception) {
            // A safe parser rejects the DOCTYPE outright; that is acceptable.
            ""
        }
        assertFalse(
            leaked.contains("TOPSECRET"),
            "XXE: the external SYSTEM entity was resolved and leaked file contents"
        )
    }
}

